  /* ---------- more films: AS and A Level first ---------- */
  function carr(g, x1, y1, x2, y2, bend = -50, a = 1, col = C.e) { if (a <= 0.01) return; const mx = (x1 + x2) / 2, my = (y1 + y2) / 2 + bend; g.save(); g.globalAlpha = cl(a); g.strokeStyle = col; g.lineWidth = 3; g.beginPath(); g.moveTo(x1, y1); g.quadraticCurveTo(mx, my, x2, y2); g.stroke(); const an = Math.atan2(y2 - my, x2 - mx); g.fillStyle = col; g.beginPath(); g.moveTo(x2, y2); g.lineTo(x2 - 13 * Math.cos(an - 0.45), y2 - 13 * Math.sin(an - 0.45)); g.lineTo(x2 - 13 * Math.cos(an + 0.45), y2 - 13 * Math.sin(an + 0.45)); g.fill(); g.restore(); }
  function bond(g, x1, y1, x2, y2, n = 1, a = 1, col = C.ink) { const an = Math.atan2(y2 - y1, x2 - x1), px = -Math.sin(an) * 5, py = Math.cos(an) * 5; if (n === 2) { line(g, x1 + px, y1 + py, x2 + px, y2 + py, col, 3, a); line(g, x1 - px, y1 - py, x2 - px, y2 - py, col, 3, a); } else line(g, x1, y1, x2, y2, col, 3, a); }
