      let i = f.scenes.length - 1; for (let j = 0; j < f.scenes.length; j++) if (T < f.scenes[j].t0 + f.scenes[j][0]) { i = j; break; }
      const s = f.scenes[i], t = Math.min(s[0], T - s.t0), u = t / s[0];
      g.save(); const fade = Math.min(1, t / 0.35, (s[0] - t) / 0.3 + 0.001); g.globalAlpha = 1; try { s[2](g, u, t, T + hold); } catch (e) { } g.restore();
